@dataclass(frozen=True)
class PracticalThrottleConfig:
    dd_moderate: float
    dd_severe: float
    scale_moderate: float
    scale_severe: float
    recover_dd: float
    rebal_cost_bps: float = 2.0


def target_scale_from_drawdown(prev_dd, cfg, current_scale):
    if prev_dd <= -cfg.dd_severe:
        return cfg.scale_severe, "severe"
    if prev_dd <= -cfg.dd_moderate:
        return cfg.scale_moderate, "moderate"
    if prev_dd >= -cfg.recover_dd:
        return 1.0, "normal"
    return current_scale, "recovery_band"


def apply_practical_throttle(base_ret, cfg):
    base_ret = pd.Series(base_ret).dropna()
    nav = 1.0
    peak = 1.0
    current_scale = 1.0
    daily_cost_per_unit = cfg.rebal_cost_bps / 10000.0
    rows = []
    for dt, base_r in base_ret.items():
        prev_dd = nav / peak - 1.0
        target_scale, state = target_scale_from_drawdown(prev_dd, cfg, current_scale)
        turnover = abs(target_scale - current_scale)
        cost = turnover * daily_cost_per_unit if turnover > 0 else 0.0
        adj_r = target_scale * float(base_r) - cost
        nav *= 1.0 + adj_r
        peak = max(peak, nav)
        prior_scale = current_scale
        current_scale = target_scale
        rows.append(
            {
                "date": dt,
                "base_return": float(base_r),
                "return": adj_r,
                "scale": target_scale,
                "prior_scale": prior_scale,
                "target_scale": target_scale,
                "state": state,
                "prev_drawdown": prev_dd,
                "turnover": turnover,
                "cost": cost,
                "nav": nav,
                "peak": peak,
                "drawdown": nav / peak - 1.0,
            }
        )
    return pd.DataFrame(rows).set_index("date")

