def call_akshare_silently(func, *args, **kwargs):
    sink = io.StringIO()
    with contextlib.redirect_stdout(sink), contextlib.redirect_stderr(sink):
        return func(*args, **kwargs)


def find_shared_cache_root():
    try:
        for child in ROOT.parent.iterdir():
            candidate = child / ".microcap_index_cache"
            if candidate.exists() and candidate != LOCAL_STRATEGY_CACHE_DIR:
                return candidate
    except Exception:
        return None
    return None


