def _decode_embedded_source(blob_parts):
    return zlib.decompress(base64.b64decode(''.join(blob_parts))).decode('utf-8')

def _install_embedded_official_modules():
    global _EMBEDDED_OFFICIAL_MODULES_INSTALLED
    if _EMBEDDED_OFFICIAL_MODULES_INSTALLED:
        return
    module_blobs = [
        ('microcap_runtime_bootstrap', _EMBEDDED_MICROCAP_RUNTIME_BOOTSTRAP_B64),
        ('fetch_wind_microcap_index', _EMBEDDED_FETCH_WIND_MICROCAP_INDEX_B64),
        ('analyze_microcap_zz1000_hedge', _EMBEDDED_ANALYZE_MICROCAP_ZZ1000_HEDGE_B64),
        ('analyze_top100_rebalance_frequency', _EMBEDDED_ANALYZE_TOP100_REBALANCE_FREQUENCY_B64),
        ('microcap_top100_mom16_biweekly_live', _EMBEDDED_MICROCAP_TOP100_MOM16_BIWEEKLY_LIVE_B64),
        ('microcap_top100_mom16_biweekly_live_v1_1', _EMBEDDED_MICROCAP_TOP100_MOM16_BIWEEKLY_LIVE_V1_1_B64),
        ('microcap_top100_mom16_biweekly_live_v1_4', _EMBEDDED_MICROCAP_TOP100_MOM16_BIWEEKLY_LIVE_V1_4_B64),
    ]
    for module_name, blob in module_blobs:
        module = types.ModuleType(module_name)
        module.__file__ = str((BOT_FILE or (BOT_DIR / 'microcap_top100_poe_bot_v1_4.py')).resolve())
        module.__package__ = ''
        sys.modules[module_name] = module
    for module_name, blob in module_blobs:
        source = _decode_embedded_source(blob)
        exec(compile(source, sys.modules[module_name].__file__, 'exec'), sys.modules[module_name].__dict__)
    _EMBEDDED_OFFICIAL_MODULES_INSTALLED = True

