# embedded runtime assets for the official v1.4 chain
_EMBEDDED_OFFICIAL_ASSETS = [
    ('mnt_strategy_data_cn.csv', _EMBEDDED_OFFICIAL_ASSET_0_B64),
    ('.microcap_index_cache/active_universe.csv', _EMBEDDED_OFFICIAL_ASSET_1_B64),
    ('.microcap_index_cache/current_st.csv', _EMBEDDED_OFFICIAL_ASSET_2_B64),
    ('.microcap_index_cache/security_master.csv', _EMBEDDED_OFFICIAL_ASSET_3_B64),
]

def _materialize_embedded_official_assets():
    root = BOT_DIR
    root.mkdir(parents=True, exist_ok=True)
    for rel_path, blob in _EMBEDDED_OFFICIAL_ASSETS:
        path = root / rel_path
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            path.write_bytes(zlib.decompress(base64.b64decode(''.join(blob))))
    (root / 'outputs').mkdir(parents=True, exist_ok=True)
    return root / 'mnt_strategy_data_cn.csv'


STRATEGIES["1.4"]["official_output_module"] = None
STRATEGIES["1.4"]["official_output_generator"] = None
ACTIVE_STRATEGY_VERSION = "1.4"


def _poe_v1_4_decode_text(blob_parts):
    return zlib.decompress(base64.b64decode("".join(blob_parts))).decode("utf-8-sig")


def _poe_v1_4_base_close_df():
    raw = _poe_v1_4_decode_text(POE_V1_4_BASE_CLOSE_B64)
    frame = pd.read_csv(io.StringIO(raw))
    frame["date"] = pd.to_datetime(frame["date"], errors="coerce")
    frame = frame.dropna(subset=["date"]).sort_values("date")
    return frame.set_index("date", drop=True).rename(
        columns={"microcap_close": "microcap", "hedge_close": "hedge"}
    )[["microcap", "hedge"]]


def _poe_v1_4_members_df():
    raw = _poe_v1_4_decode_text(POE_V1_4_MEMBERS_B64)
    frame = pd.read_csv(io.StringIO(raw), dtype={"symbol": str})
    if "symbol" in frame.columns:
        frame["symbol"] = frame["symbol"].astype(str).str.zfill(6)
    if "code" not in frame.columns and "symbol" in frame.columns:
        frame["code"] = frame["symbol"]
    if "target_weight" not in frame.columns:
        frame["target_weight"] = 1.0 / TOP_N
    return frame


def _poe_v1_4_meta():
    return json.loads(_poe_v1_4_decode_text(POE_V1_4_META_B64))


def get_strategy(version=None):
    return STRATEGIES["1.4"].copy()


def set_active_strategy(version):
    global ACTIVE_STRATEGY_VERSION
    ACTIVE_STRATEGY_VERSION = "1.4"
    return None


def resolve_strategy_from_query(query_text):
    set_active_strategy("1.4")
    return get_strategy(), strip_strategy_version_tokens(query_text)


def build_intro_text():
    return (
        "Top100 microcap hedge strategy - Poe v1.4 standalone live bot\n\n"
        f"- Send {CMD_SIGNAL}: rebuild the v1.4 signal from live network data\n"
        f"- Send {CMD_REALTIME}: rebuild the v1.4 realtime signal from live network data\n"
        f"- Send {CMD_MEMBERS}: rebuild and return the current v1.4 effective members\n"
        f"- Send {CMD_CHANGES}: return the current v1.4 rebalance count summary\n"
        f"- Send {CMD_PERFORMANCE}: return v1.4 performance summary\n"
        "This Poe file is fixed to v1.4 and does not import local main strategy scripts."
    )


def build_help_text():
    return (
        "Supported commands:\n"
        f"1. {CMD_SIGNAL}\n"
        f"2. {CMD_REALTIME}\n"
        f"3. {CMD_MEMBERS}\n"
        f"4. {CMD_CHANGES}\n"
        f"5. {CMD_REALTIME_CHANGES}\n"
        f"6. {CMD_PERFORMANCE} 5Y / {CMD_PERFORMANCE} 2024 YTD / last 3Y\n"
        f"7. {CMD_PARAMS}\n\n"
        "Note: signal commands run the full standalone live rebuild; no embedded signal result is used."
    )


def normalize_command(query_text):
    text = (query_text or "").strip()
    if not text:
        return CMD_REALTIME
    if "\u53c2\u6570" in text:
        return CMD_PARAMS
    if PERFORMANCE_PATTERN.search(text):
        return CMD_PERFORMANCE
    if "\u5b9e\u65f6" in text and "\u8fdb\u51fa\u540d\u5355" in text:
        return CMD_REALTIME_CHANGES
    if "\u8fdb\u51fa\u540d\u5355" in text:
        return CMD_CHANGES
    if "\u6210\u5206\u80a1" in text:
        return CMD_MEMBERS
    if "\u4fe1\u53f7" in text:
        return CMD_REALTIME
    return "help"


def _poe_v1_4_static_context():
    set_active_strategy("1.4")
    meta = _poe_v1_4_meta()
    close_df = _poe_v1_4_base_close_df()
    members = _poe_v1_4_members_df()
    result = run_selected_strategy_backtest(close_df)
    signal_df = build_latest_signal(result)
    enter_count = int(meta.get("member_enter_count") or 0)
    exit_count = int(meta.get("member_exit_count") or 0)
    changes_df = pd.DataFrame(
        [{"action": "enter"} for _ in range(enter_count)]
        + [{"action": "exit"} for _ in range(exit_count)]
    )
    signal_df = augment_signal_with_member_rebalance(signal_df, changes_df)
    latest_rebalance = meta.get("latest_rebalance_date") or str(pd.Timestamp(close_df.index[-1]).date())
    previous_rebalance = meta.get("previous_rebalance_date")
    next_rebalance = meta.get("next_rebalance_date")
    effective_date = resolve_rebalance_effective_date(close_df.index, latest_rebalance)
    if not members.empty:
        members["signal_date"] = latest_rebalance
        members["effective_date"] = effective_date
    freshness_date = meta.get("latest_nav_date") or str(pd.Timestamp(close_df.index[-1]).date())
    context = {
        "close_df": close_df,
        "result": result,
        "latest_signal": signal_df,
        "latest_rebalance": str(pd.Timestamp(latest_rebalance).date()),
        "prev_rebalance": None if previous_rebalance is None else str(pd.Timestamp(previous_rebalance).date()),
        "next_rebalance": None if next_rebalance is None else str(pd.Timestamp(next_rebalance).date()),
        "effective_rebalance": str(pd.Timestamp(latest_rebalance).date()),
        "rebalance_effective_date": effective_date,
        "target_members": members.copy(),
        "effective_members": members.copy(),
        "changes_df": changes_df,
        "freshness": {
            "status": "standalone_base_plus_live_quotes",
            "latest_trade_date": str(pd.Timestamp(freshness_date).date()),
            "current_date": str(pd.Timestamp.now().normalize().date()),
            "stale_calendar_days": max(0, int((pd.Timestamp.now().normalize() - pd.Timestamp(freshness_date).normalize()).days)),
        },
        "rebuild_meta": {
            "strategy_version": "1.4",
            "strategy_label": get_strategy_label(),
            "fixed_hedge_ratio": get_strategy_hedge_ratio(),
            "core_params": meta.get("core_params") or build_context_core_params(),
            "candidate_pool": "standalone_effective_100",
            "history_symbols_ok": int(meta.get("history_days") or len(close_df)),
            "history_symbols_failed": 0,
            "strict_validated": True,
            "validated_exact_pools": ["standalone_effective_100"],
            "effective_member_count": int(len(members)),
            "last_trade_signal_date": None,
            "last_trade_signal_action": None,
        },
    }
    last_trade_date, last_trade_action = get_last_trade_signal_info(context)
    context["rebuild_meta"]["last_trade_signal_date"] = last_trade_date
    context["rebuild_meta"]["last_trade_signal_action"] = last_trade_action
    return context


def _poe_v1_4_live_context(force_refresh=True):
    set_active_strategy("1.4")
    return build_official_v1_4_context(force_refresh=True)


def build_official_v1_4_context(force_refresh=False):
    _materialize_embedded_official_assets()
    _install_embedded_official_modules()
    module = importlib.import_module("microcap_top100_mom16_biweekly_live_v1_4")
    summary, signal_df, result = module.generate_v1_4_outputs()
    signal_df = pd.DataFrame(signal_df).copy()
    if signal_df.empty:
        raise RuntimeError("embedded official v1.4 module returned no signal")
    signal_df["date"] = pd.to_datetime(signal_df["date"], errors="coerce")
    result = pd.DataFrame(result).copy()
    if not isinstance(result.index, pd.DatetimeIndex):
        if "date" in result.columns:
            result["date"] = pd.to_datetime(result["date"], errors="coerce")
            result = result.set_index("date", drop=True)
        else:
            result.index = pd.to_datetime(result.index)
    result = result.sort_index()
    close_df = result[["microcap_close", "hedge_close"]].rename(
        columns={"microcap_close": "microcap", "hedge_close": "hedge"}
    )
    row = signal_df.iloc[0]
    latest_rebalance = (
        summary.get("latest_rebalance_date")
        or summary.get("latest_rebalance")
        or pd.Timestamp(row["date"]).strftime("%Y-%m-%d")
    )
    prev_rebalance = summary.get("previous_rebalance_date") or summary.get("prev_rebalance")
    next_rebalance = summary.get("next_rebalance_date") or summary.get("next_rebalance")
    effective_rebalance = summary.get("effective_rebalance") or latest_rebalance
    rebalance_effective_date = summary.get("rebalance_effective_date")
    if not rebalance_effective_date:
        rebalance_effective_date = resolve_rebalance_effective_date(result.index, latest_rebalance)
    enter_count = int(pd.to_numeric(row.get("member_enter_count", 0), errors="coerce") or 0)
    exit_count = int(pd.to_numeric(row.get("member_exit_count", 0), errors="coerce") or 0)
    changes_df = pd.DataFrame(
        [{"action": "enter"} for _ in range(enter_count)]
        + [{"action": "exit"} for _ in range(exit_count)]
    )
    freshness_date = summary.get("latest_nav_date") or summary.get("latest_trade_date") or row.get("date")
    freshness = {
        "status": "embedded_official_v1_4",
        "latest_trade_date": str(pd.Timestamp(freshness_date).date()),
        "current_date": str(pd.Timestamp.now().normalize().date()),
        "stale_calendar_days": max(
            0,
            int((pd.Timestamp.now().normalize() - pd.Timestamp(freshness_date).normalize()).days),
        ),
    }
    return {
        "close_df": close_df,
        "result": result,
        "latest_signal": signal_df,
        "latest_rebalance": str(pd.Timestamp(latest_rebalance).date()),
        "prev_rebalance": None if prev_rebalance is None else str(pd.Timestamp(prev_rebalance).date()),
        "next_rebalance": None if next_rebalance is None else str(pd.Timestamp(next_rebalance).date()),
        "effective_rebalance": str(pd.Timestamp(effective_rebalance).date()),
        "rebalance_effective_date": rebalance_effective_date,
        "target_members": pd.DataFrame(),
        "effective_members": pd.DataFrame(),
        "changes_df": changes_df,
        "freshness": freshness,
        "rebuild_meta": {
            "strategy_version": "1.4",
            "strategy_label": get_strategy_label(),
            "fixed_hedge_ratio": get_strategy_hedge_ratio(),
            "core_params": (summary or {}).get("core_params") or build_context_core_params(),
            "candidate_pool": "embedded_official_v1_4",
            "history_symbols_ok": int(len(result)),
            "history_symbols_failed": 0,
            "strict_validated": True,
            "validated_exact_pools": ["embedded_official_v1_4"],
            "last_trade_signal_date": None,
            "last_trade_signal_action": None,
        },
    }


def _poe_v1_4_fetch_realtime_signal():
    context = _poe_v1_4_live_context(force_refresh=True)
    member_symbols = context["effective_members"]["symbol"].astype(str).str.zfill(6).tolist()
    if not member_symbols:
        raise RuntimeError("standalone base has no effective members")
    quotes_df, quote_source = build_realtime_quote_frame(member_symbols)
    if quotes_df.empty:
        raise RuntimeError("failed to fetch realtime quotes for effective members")
    quotes_df = quotes_df.set_index("code")
    member_returns = []
    available_rows = 0
    for sym in member_symbols:
        if sym not in quotes_df.index:
            continue
        rt_price = pd.to_numeric(quotes_df.at[sym, "rt_price"], errors="coerce")
        prev_close = pd.to_numeric(quotes_df.at[sym, "prev_close"], errors="coerce") if "prev_close" in quotes_df.columns else np.nan
        if pd.isna(rt_price) or rt_price <= 0 or pd.isna(prev_close) or prev_close <= 0:
            continue
        member_returns.append(float(rt_price / prev_close - 1.0))
        available_rows += 1
    if not member_returns:
        raise RuntimeError("not enough realtime member prices to estimate the microcap proxy")
    min_realtime_quotes = min(len(member_symbols), max(1, int(np.ceil(len(member_symbols) * 0.95))))
    if available_rows < min_realtime_quotes:
        raise RuntimeError(
            f"realtime valid quotes {available_rows}/{len(member_symbols)}; "
            f"below minimum {min_realtime_quotes}/{len(member_symbols)}; refuse to output realtime signal"
        )

    close_df = context["close_df"]
    now_ts = china_now().tz_localize(None)
    session_date = now_ts.normalize()
    base_df = close_df.loc[pd.to_datetime(close_df.index).normalize() < session_date].copy()
    if base_df.empty:
        base_df = close_df.iloc[:-1].copy() if len(close_df) > 1 else close_df.copy()
    base_microcap = float(base_df["microcap"].iloc[-1])
    microcap_rt_close = base_microcap * (1.0 + float(np.mean(member_returns)))
    try:
        hedge_rt_close = fetch_hedge_realtime_quote()
        hedge_source = "eastmoney"
    except Exception:
        hedge_rt_close = float(base_df["hedge"].iloc[-1])
        hedge_source = "latest_base_close_fallback"

    snapshot_ts = now_ts
    if snapshot_ts <= pd.Timestamp(base_df.index[-1]):
        snapshot_ts = pd.Timestamp(base_df.index[-1]) + pd.Timedelta(seconds=1)
    rt_close_df = base_df.copy()
    rt_close_df.loc[snapshot_ts, ["microcap", "hedge"]] = [microcap_rt_close, hedge_rt_close]
    rt_close_df = rt_close_df.sort_index()
    rt_result = run_selected_strategy_backtest(rt_close_df)
    signal_df = build_latest_signal(rt_result)
    signal_df = augment_signal_with_member_rebalance(signal_df, context.get("changes_df"))
    jitter_level, jitter_note = classify_tail_jitter_risk(float(signal_df.iloc[0]["momentum_gap"]))
    signal_df["quote_source"] = quote_source
    signal_df["hedge_quote_source"] = hedge_source
    signal_df["member_price_count"] = available_rows
    signal_df["member_count"] = len(member_symbols)
    signal_df["realtime_quote_min_required"] = min_realtime_quotes
    signal_df["latest_anchor_trade_date"] = str(pd.Timestamp(base_df.index[-1]).date())
    signal_df["tail_jitter_risk"] = jitter_level
    signal_df["tail_jitter_note"] = jitter_note
    context["close_df"] = rt_close_df
    context["result"] = rt_result
    context["latest_signal"] = signal_df
    context["freshness"]["latest_trade_date"] = str(pd.Timestamp(base_df.index[-1]).date())
    return context, signal_df, available_rows, len(member_symbols)


def handle_signal(force_refresh=False):
    context = build_official_v1_4_context(force_refresh=True)
    row = context["latest_signal"].iloc[0]
    csv_bytes = context["latest_signal"].to_csv(index=False).encode("utf-8-sig")
    attachments = [build_thread_context_attachment(context)]
    body = format_signal_summary(row, context)
    body += "\n\nData mode: embedded official v1.4 code path; proxy rebuild output is not used."
    return body, csv_bytes, attachments


